// ─── File: LockerLldDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.locker;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class LockerLldDemo {
    private static final Logger log = Logger.getLogger(LockerLldDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PricingStrategy pricing = new SizePricing(); // Strategy: pricing varies by size
        LockerVault vault = new LockerVault(pricing);
        vault.addLocker(new Locker("L1", "SMALL"));
        vault.addLocker(new Locker("L2", "MEDIUM"));
        vault.addLocker(new Locker("L3", "LARGE"));

        Customer rajesh = new Customer("SAV2001", "Rajesh");
        Customer priya = new Customer("CUR3001", "Priya");

        log.info("=== Book lockers (LLD model traced end to end) ===");
        Booking b1 = vault.book(rajesh, "MEDIUM");
        if (b1 != null) log.info(() -> "Booked " + b1.getLocker().getId()
                + " for " + b1.getCustomer().getName() + " @ Rs." + b1.getPrice());

        Booking b2 = vault.book(priya, "LARGE");
        if (b2 != null) log.info(() -> "Booked " + b2.getLocker().getId()
                + " for " + b2.getCustomer().getName() + " @ Rs." + b2.getPrice());

        log.info("=== No free MEDIUM left -> clean failure ===");
        Booking b3 = vault.book(priya, "MEDIUM"); // already taken
        if (b3 == null) log.warning("No free MEDIUM locker available");
    }
}

// ─── model/Locker.java — owns its OWN state transitions (thin orchestration) ───
class Locker {
    private final String id;
    private final String size;
    private boolean occupied = false;
    Locker(String id, String size) { this.id = id; this.size = size; }
    String getId() { return id; }
    String getSize() { return size; }
    boolean isOccupied() { return occupied; }
    void assign() { this.occupied = true; }   // entity controls its transition
    void release() { this.occupied = false; }
}

// ─── model/Customer.java ───
class Customer {
    private final String accountId;
    private final String name;
    Customer(String accountId, String name) { this.accountId = accountId; this.name = name; }
    String getName() { return name; }
}

// ─── model/Booking.java — links customer + locker + price ───
class Booking {
    private final Customer customer;
    private final Locker locker;
    private final BigDecimal price;
    Booking(Customer customer, Locker locker, BigDecimal price) {
        this.customer = customer; this.locker = locker; this.price = price;
    }
    Customer getCustomer() { return customer; }
    Locker getLocker() { return locker; }
    BigDecimal getPrice() { return price; }
}

// ─── service/LockerVault.java — manages lockers, finds a free one ───
class LockerVault {
    private static final Logger log = Logger.getLogger(LockerVault.class.getName());
    private final List<Locker> lockers = new ArrayList<>(); // composition: vault owns lockers
    private final PricingStrategy pricing;
    LockerVault(PricingStrategy pricing) { this.pricing = pricing; }

    void addLocker(Locker l) { lockers.add(l); }

    // Concurrency note: in a real multi-threaded vault, synchronize assignment.
    synchronized Booking book(Customer customer, String size) {
        for (Locker l : lockers) {
            if (!l.isOccupied() && l.getSize().equals(size)) {
                l.assign();                          // entity owns its state change
                BigDecimal price = pricing.price(size);
                return new Booking(customer, l, price);
            }
        }
        return null; // clean failure — no exception needed for a normal "none free"
    }
}

// ─── pricing/PricingStrategy.java — Strategy ONLY because pricing truly varies ───
interface PricingStrategy {
    BigDecimal price(String size);
}

// ─── pricing/SizePricing.java ───
class SizePricing implements PricingStrategy {
    public BigDecimal price(String size) {
        switch (size) {
            case "SMALL":  return new BigDecimal("1500");
            case "MEDIUM": return new BigDecimal("3000");
            case "LARGE":  return new BigDecimal("5000");
            default:       return new BigDecimal("3000");
        }
    }
}

// ─── util/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
